challenge.verificationSource:
mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("text=leetcode dict=[leet,code]","true"),
        ("text=apple dict=[app]","false"),
        ("text=aaaa dict=[a,aa]","true"),
        ("text=catsanddog dict=[cat,cats,and,sand,dog]","true"),
        ("text=ab dict=[a]","false"),
        ("  \ntext=leetcode dict=[leet,code]\n  ","true"),
        ("\ntext=ab dict=[a]\n","false")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS word-break-dp");
}
